#include "table_design_internal.hpp"
#include <QMap>
#include <algorithm>
namespace navidog {
using namespace design;
namespace {
QString paren(const QString& source,int ordinal=0){auto ts=tokens(source,K::SQLite);int depth=0,start=-1;for(const auto& t:ts){if(t.kind!=sql::TokenKind::Symbol)continue;if(t.text=="("){if(depth++==0){if(ordinal--==0)start=t.end;}}else if(t.text==")" && --depth==0 && start>=0)return slice(source,start,t.begin);}return {};}
QStringList commaParts(const QString& source){auto ts=tokens(source,K::SQLite);int depth=0,start=0;QStringList out;for(const auto& t:ts){if(t.kind!=sql::TokenKind::Symbol)continue;if(t.text=="(")++depth;else if(t.text==")")--depth;else if(t.text=="," && depth==0){out<<slice(source,start,t.begin).trimmed();start=t.end;}}out<<slice(source,start,source.toUtf8().size()).trimmed();return out;}
void parseIndex(TableObject& o,const QString& ddl,K k){o.sql=ddl;auto ts=tokens(ddl,k);int on=-1,start=-1,end=-1,depth=0;for(int i=0;i<ts.size();++i){auto t=ts[i];if(t.kind==sql::TokenKind::Word && t.text.compare("ON",Qt::CaseInsensitive)==0 && on<0)on=i;if(on<0)continue;if(t.kind==sql::TokenKind::Word && t.text.compare("USING",Qt::CaseInsensitive)==0 && i+1<ts.size())o.method=ts[i+1].text;if(t.kind==sql::TokenKind::Symbol){if(t.text=="("){if(depth++==0 && start<0)start=t.end;}else if(t.text==")" && --depth==0 && start>=0){end=t.begin;auto tail=slice(ddl,t.end,ddl.toUtf8().size()).trimmed();if(tail.endsWith(';'))tail.chop(1);if(tail.startsWith("WHERE ",Qt::CaseInsensitive))o.predicate=tail.mid(6).trimmed();else if(!tail.isEmpty())return;break;}}}if(start>=0 && end>=start){o.expression=slice(ddl,start,end);o.sql.clear();}}
void foreignRule(TableObject& o,const QString& clause){auto ts=tokens(clause,K::SQLite);for(int i=0;i<ts.size();++i){auto t=ts[i].text.toUpper();if(t=="REFERENCES" && i+1<ts.size()){int j=i+1;auto first=unquote(ts[j++].text);if(j+1<ts.size() && ts[j].text=="."){o.referenceSchema=first;o.referenceTable=unquote(ts[++j].text);++j;}else o.referenceTable=first;if(j<ts.size() && ts[j].text=="("){int start=ts[j].end;while(j<ts.size() && ts[j].text!=")")++j;if(j<ts.size())o.referenceColumns=parseIdentifierList(slice(clause,start,ts[j].begin));}}
        if(t=="ON" && i+2<ts.size()){auto which=ts[i+1].text.toUpper(),rule=ts[i+2].text.toUpper();if((rule=="SET" || rule=="NO") && i+3<ts.size())rule+=" "+ts[i+3].text.toUpper();if(which=="DELETE")o.onDelete=rule;if(which=="UPDATE")o.onUpdate=rule;}
        if(t=="DEFERRABLE" && (i==0 || ts[i-1].text.compare("NOT",Qt::CaseInsensitive)!=0))o.deferrable=true;if(t=="INITIALLY" && i+1<ts.size())o.initiallyDeferred=ts[i+1].text.compare("DEFERRED",Qt::CaseInsensitive)==0;
    }}
void sqliteDetails(Database& db,const ConnectionProfile&,TableDefinition& d,const Cancellation& cancel){auto schema=d.node.schema.isEmpty()?QString("main"):d.node.schema;auto qschema=quoteIdentifier(schema,K::SQLite);auto r=read(db,"SELECT sql FROM "+qschema+".sqlite_schema WHERE type='table' AND name="+lit(d.node.object,K::SQLite),cancel);if(r.rows.isEmpty())fail("表不存在");d.rawSql=r.rows[0][0].toString();auto ts=tokens(d.rawSql,K::SQLite);int depth=0,end=0;for(auto t:ts){if(t.text=="(")++depth;else if(t.text==")" && --depth==0){end=t.end;break;}}auto tail=slice(d.rawSql,end,d.rawSql.toUtf8().size()).toUpper();d.withoutRowid=tail.contains("WITHOUT ROWID");d.strict=tail.contains("STRICT");int ordinal=0;
    for(auto part:commaParts(paren(d.rawSql))){auto pts=tokens(part,K::SQLite);if(pts.isEmpty())continue;int first=0;QString cname;if(pts[first].text.compare("CONSTRAINT",Qt::CaseInsensitive)==0 && pts.size()>2){cname=unquote(pts[1].text);first=2;}auto word=pts[first].text.toUpper();const bool table=word=="PRIMARY" || word=="UNIQUE" || word=="CHECK" || word=="FOREIGN";
        if(table && word=="PRIMARY"){d.primaryKeyName=cname;continue;}
        auto col=std::find_if(d.columns.begin(),d.columns.end(),[&](const auto& c){return c.name==unquote(pts[0].text);});
        if(!table && col==d.columns.end())fail("无法完整解析 SQLite 字段定义");
        auto addConstraint=[&](QString clause,QString type,QString constraintName,QString column){TableObject o;o.originalName=o.name=constraintName.isEmpty()?QString(type.toLower()+"_"+QString::number(++ordinal)):constraintName;o.sql=clause;if(type=="CHECK"){o.kind=TableObjectKind::Check;o.expression=paren(clause);}else if(type=="UNIQUE"){o.kind=TableObjectKind::Index;o.constraint=o.unique=true;o.expression=column.isEmpty()?paren(clause):quoteIdentifier(column,K::SQLite);if(!column.isEmpty())o.sql="UNIQUE ("+quoteIdentifier(column,K::SQLite)+")"+clause.mid(QString("UNIQUE").size());}else{o.kind=TableObjectKind::ForeignKey;o.columns=column.isEmpty()?parseIdentifierList(paren(clause)):QStringList{column};foreignRule(o,clause);if(!column.isEmpty())o.sql="FOREIGN KEY ("+quoteIdentifier(column,K::SQLite)+") "+clause;}d.objects<<o;};
        if(table){addConstraint(part,word=="FOREIGN"?"FOREIGN":word,cname,{});continue;}
        col->attributes.clear();for(int i=1;i<pts.size();++i){auto token=pts[i];auto w=token.text.toUpper();if(w=="AUTOINCREMENT")col->autoIncrement=true;if(w=="COLLATE" && i+1<pts.size())col->collation=unquote(pts[++i].text);
            if(w=="GENERATED" || w=="AS"){auto start=i;while(i<pts.size() && pts[i].text!="(")++i;if(i<pts.size()){int j=i,level=0;for(;j<pts.size();++j){if(pts[j].text=="(")++level;if(pts[j].text==")" && --level==0)break;}if(j>=pts.size())fail("生成字段定义未闭合");col->generatedExpression=slice(part,pts[i].end,pts[j].begin);col->generation=j+1<pts.size() && pts[j+1].text.compare("STORED",Qt::CaseInsensitive)==0?"STORED":"VIRTUAL";col->protectedReason.clear();i=j+1;Q_UNUSED(start);}}
            if(w=="CHECK" || w=="UNIQUE" || w=="REFERENCES"){int stop=pts.size();if(w=="CHECK"){int j=i+1,level=0;for(;j<pts.size();++j){if(pts[j].text=="(")++level;if(pts[j].text==")" && --level==0){stop=j+1;break;}}}else if(w=="UNIQUE"){stop=i+1;if(stop<pts.size() && pts[stop].text.compare("ON",Qt::CaseInsensitive)==0)stop=qMin(stop+3,int(pts.size()));}
                auto clause=slice(part,token.begin,stop<pts.size()?pts[stop].begin:part.toUtf8().size());addConstraint(clause,w=="REFERENCES"?"FOREIGN":w,cname,col->name);i=stop-1;}
        }
    }
    r=read(db,"SELECT name,sql FROM "+qschema+".sqlite_schema WHERE tbl_name="+lit(d.node.object,K::SQLite)+" AND type IN ('index','trigger') AND sql IS NOT NULL ORDER BY type,name",cancel);for(auto row:r.rows){TableObject o;o.name=o.originalName=row[0].toString();auto ddl=row[1].toString();o.kind=ddl.trimmed().startsWith("CREATE TRIGGER",Qt::CaseInsensitive)?TableObjectKind::Trigger:TableObjectKind::Index;if(o.kind==TableObjectKind::Trigger)o.sql=ddl;else{o.unique=ddl.contains(QRegularExpression("^CREATE\\s+UNIQUE\\s+INDEX",QRegularExpression::CaseInsensitiveOption));parseIndex(o,ddl,K::SQLite);}d.objects<<o;}
}
}
void readTableDetails(Database& db,const ConnectionProfile& p,TableDefinition& d,const Cancellation& cancel){auto k=p.driver;auto q=[&](const QString& s){return read(db,s,cancel);};auto l=[&](QString s){return lit(s,k);};auto table=tableQualifiedName(p,d.node);auto filter=" WHERE table_schema="+l(mysql(k)?d.node.database:d.node.schema)+" AND table_name="+l(d.node.object);
    if(k==K::SQLite){sqliteDetails(db,p,d,cancel);d.detailsLoaded=true;return;}
    if(mysql(k)){
        auto mode=q("SELECT @@SESSION.sql_mode");if(!mode.rows.isEmpty())d.sqlMode=mode.rows[0][0].toString();
        auto r=q("SELECT engine,table_collation,row_format,table_comment FROM information_schema.tables"+filter);if(!r.rows.isEmpty()){d.engine=r.rows[0][0].toString();d.collation=r.rows[0][1].toString();d.charset=d.collation.section('_',0,0);d.rowFormat=r.rows[0][2].toString();d.comment=r.rows[0][3].toString();}
        r=q("SELECT index_name,non_unique,seq_in_index,column_name,sub_part,collation,index_type,index_comment FROM information_schema.statistics"+filter+" ORDER BY index_name,seq_in_index");QMap<QString,int> indexes;for(auto row:r.rows){auto name=row[0].toString();if(name=="PRIMARY"){d.primaryKeyName=name;for(auto& column:d.columns)if(column.name==row[3].toString())column.primaryKey=row[2].toInt();continue;}if(!indexes.contains(name)){TableObject o;o.originalName=o.name=name;o.unique=!row[1].toBool();o.method=row[6].toString();o.comment=row[7].toString();indexes[name]=d.objects.size();d.objects<<o;}auto& o=d.objects[indexes[name]];if(row[3].isNull()){o.protectedReason="表达式索引请使用完整定义编辑";continue;}QString field=quoteIdentifier(row[3].toString(),k);if(!row[4].isNull())field+="("+row[4].toString()+")";if(row[5].toString()=="D")field+=" DESC";if(!o.expression.isEmpty())o.expression+=", ";o.expression+=field;}
        r=q("SELECT k.constraint_name,k.column_name,k.referenced_table_schema,k.referenced_table_name,k.referenced_column_name,r.delete_rule,r.update_rule FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.constraint_name=k.constraint_name AND r.table_name=k.table_name WHERE k.table_schema="+l(d.node.database)+" AND k.table_name="+l(d.node.object)+" ORDER BY k.constraint_name,k.ordinal_position");QMap<QString,int> fks;for(auto row:r.rows){auto name=row[0].toString();if(!fks.contains(name)){TableObject o;o.kind=TableObjectKind::ForeignKey;o.originalName=o.name=name;o.referenceSchema=row[2].toString();o.referenceTable=row[3].toString();o.onDelete=row[5].toString();o.onUpdate=row[6].toString();fks[name]=d.objects.size();d.objects<<o;}auto& o=d.objects[fks[name]];o.columns<<row[1].toString();o.referenceColumns<<row[4].toString();}
        auto version=detectVersion(k,db.serverVersion());if(k==K::OceanBase || (version!=DatabaseVersion::MySQL5_7 && version!=DatabaseVersion::Unknown)){
            r=q("SELECT c.constraint_name,c.check_clause"+QString(k==K::MySQL?",t.enforced":"")+" FROM information_schema.check_constraints c JOIN information_schema.table_constraints t ON t.constraint_schema=c.constraint_schema AND t.constraint_name=c.constraint_name"+QString(k==K::MariaDB?" AND c.table_name=t.table_name":"")+" WHERE t.table_schema="+l(d.node.database)+" AND t.table_name="+l(d.node.object)+" AND t.constraint_type='CHECK' ORDER BY c.constraint_name");for(auto row:r.rows){TableObject o;o.kind=TableObjectKind::Check;o.originalName=o.name=row[0].toString();o.expression=row[1].toString();if(k==K::MySQL)o.expression=design::mysqlMetadataExpression(o.expression,o.protectedReason);else if(k==K::MariaDB && o.expression.contains('\\'))o.protectedReason="检查表达式含复杂转义，请使用完整 SQL 修改该约束。";if(row.size()>2)o.enabled=row[2].toString()!="NO";d.objects<<o;}}
        r=q("SELECT trigger_name FROM information_schema.triggers WHERE trigger_schema="+l(d.node.database)+" AND event_object_table="+l(d.node.object)+" ORDER BY trigger_name");for(auto row:r.rows){TableObject o;o.kind=TableObjectKind::Trigger;o.originalName=o.name=row[0].toString();auto ddl=q("SHOW CREATE TRIGGER "+qualifiedObject(p,d.node,o.name));if(ddl.rows.isEmpty())fail("未读取到触发器定义");int col=ddl.columns.indexOf("SQL Original Statement");if(col<0)col=2;if(ddl.rows[0].size()<=col)fail("触发器定义格式不完整");o.sql=ddl.rows[0][col].toString();if(ddl.rows[0].size()>1)o.sqlMode=ddl.rows[0][1].toString();d.objects<<o;}
    }else if(navidog::usesNativePostgres(k)){
        auto r=q("SELECT COALESCE(obj_description(c.oid,'pg_class'),''),COALESCE(t.spcname,'') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_tablespace t ON t.oid=c.reltablespace WHERE n.nspname="+l(d.node.schema)+" AND c.relname="+l(d.node.object));if(!r.rows.isEmpty()){d.comment=r.rows[0][0].toString();d.tablespace=r.rows[0][1].toString();}
        r=q("SELECT a.attname,COALESCE(col_description(a.attrelid,a.attnum),'') FROM pg_attribute a WHERE a.attrelid="+l(table)+"::regclass AND a.attnum>0 AND NOT a.attisdropped");for(auto row:r.rows)for(auto& c:d.columns)if(c.name==row[0].toString())c.comment=row[1].toString();
        r=q("SELECT c.conname,c.contype,pg_get_constraintdef(c.oid,true),c.condeferrable::int,c.condeferred::int,c.convalidated::int FROM pg_constraint c WHERE c.conrelid="+l(table)+"::regclass ORDER BY c.conname");for(auto row:r.rows){auto type=row[1].toString();if(type=="p"){d.primaryKeyName=row[0].toString();continue;}if(type!="u" && type!="f" && type!="c")continue;TableObject o;o.name=o.originalName=row[0].toString();auto def=row[2].toString();o.deferrable=row[3].toBool();o.initiallyDeferred=row[4].toBool();o.enabled=row[5].toBool();if(type=="u"){o.kind=TableObjectKind::Index;o.constraint=o.unique=true;o.expression=paren(def);}else if(type=="c"){o.kind=TableObjectKind::Check;o.expression=paren(def);}else{o.kind=TableObjectKind::ForeignKey;o.columns=parseIdentifierList(paren(def));foreignRule(o,def);}d.objects<<o;}
        r=q("SELECT c.relname,pg_get_indexdef(i.indexrelid),i.indisunique::int,COALESCE(obj_description(i.indexrelid,'pg_class'),'') FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid="+l(table)+"::regclass AND NOT i.indisprimary AND NOT EXISTS(SELECT 1 FROM pg_constraint t WHERE t.conindid=i.indexrelid) ORDER BY c.relname");for(auto row:r.rows){TableObject o;o.name=o.originalName=row[0].toString();o.unique=row[2].toBool();o.comment=row[3].toString();parseIndex(o,row[1].toString(),k);d.objects<<o;}
        r=q("SELECT tgname,pg_get_triggerdef(oid,true),tgenabled FROM pg_trigger WHERE tgrelid="+l(table)+"::regclass AND NOT tgisinternal ORDER BY tgname");for(auto row:r.rows){TableObject o;o.kind=TableObjectKind::Trigger;o.name=o.originalName=row[0].toString();o.sql=row[1].toString();o.enabled=row[2].toString()!="D";if(row[2].toString()=="A" || row[2].toString()=="R")o.protectedReason="ALWAYS / REPLICA 触发器请保留原激活策略并使用 SQL 修改";d.objects<<o;}
    }else if(k==K::SQLServer){
        auto oid="OBJECT_ID("+l(table)+")";auto r=q("SELECT CONVERT(nvarchar(max),ep.value),ep.minor_id FROM sys.extended_properties ep WHERE ep.class=1 AND ep.major_id="+oid+" AND ep.name=N'MS_Description'");for(auto row:r.rows){if(row[1].toInt()==0)d.comment=row[0].toString();}
        r=q("SELECT c.name,CONVERT(nvarchar(max),ep.value),dc.name FROM sys.columns c LEFT JOIN sys.extended_properties ep ON ep.class=1 AND ep.major_id=c.object_id AND ep.minor_id=c.column_id AND ep.name=N'MS_Description' LEFT JOIN sys.default_constraints dc ON dc.object_id=c.default_object_id WHERE c.object_id="+oid);for(auto row:r.rows)for(auto& c:d.columns)if(c.name==row[0].toString()){c.comment=row[1].toString();c.defaultConstraint=row[2].toString();}
        r=q("SELECT i.name,i.is_unique,i.is_primary_key,i.is_unique_constraint,i.type_desc,c.name,ic.is_descending_key,ic.is_included_column,i.filter_definition FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.object_id="+oid+" AND i.name IS NOT NULL ORDER BY i.index_id,ic.key_ordinal,ic.index_column_id");QMap<QString,int> indexes;for(auto row:r.rows){auto name=row[0].toString();if(row[2].toBool()){d.primaryKeyName=name;continue;}if(!indexes.contains(name)){TableObject o;o.name=o.originalName=name;o.unique=row[1].toBool();o.constraint=row[3].toBool();o.method=row[4].toString();o.predicate=row[8].toString();indexes[name]=d.objects.size();d.objects<<o;}auto& o=d.objects[indexes[name]];if(row[7].toBool()){o.protectedReason="包含列索引请使用 SQL 修改，以保留 INCLUDE 列";continue;}if(!o.expression.isEmpty())o.expression+=", ";o.expression+=quoteIdentifier(row[5].toString(),k)+(row[6].toBool()?" DESC":"");}
        r=q("SELECT f.name,c.name,rs.name,rt.name,rc.name,f.delete_referential_action_desc,f.update_referential_action_desc,f.is_disabled FROM sys.foreign_keys f JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id JOIN sys.columns c ON c.object_id=fc.parent_object_id AND c.column_id=fc.parent_column_id JOIN sys.tables rt ON rt.object_id=fc.referenced_object_id JOIN sys.schemas rs ON rs.schema_id=rt.schema_id JOIN sys.columns rc ON rc.object_id=fc.referenced_object_id AND rc.column_id=fc.referenced_column_id WHERE f.parent_object_id="+oid+" ORDER BY f.name,fc.constraint_column_id");QMap<QString,int> fks;for(auto row:r.rows){auto name=row[0].toString();if(!fks.contains(name)){TableObject o;o.kind=TableObjectKind::ForeignKey;o.name=o.originalName=name;o.referenceSchema=row[2].toString();o.referenceTable=row[3].toString();o.onDelete=row[5].toString().replace('_',' ');o.onUpdate=row[6].toString().replace('_',' ');o.enabled=!row[7].toBool();fks[name]=d.objects.size();d.objects<<o;}auto& o=d.objects[fks[name]];o.columns<<row[1].toString();o.referenceColumns<<row[4].toString();}
        r=q("SELECT name,definition,is_disabled FROM sys.check_constraints WHERE parent_object_id="+oid+" ORDER BY name");for(auto row:r.rows){TableObject o;o.kind=TableObjectKind::Check;o.name=o.originalName=row[0].toString();o.expression=row[1].toString();o.enabled=!row[2].toBool();d.objects<<o;}
        r=q("SELECT name,OBJECT_DEFINITION(object_id),is_disabled FROM sys.triggers WHERE parent_id="+oid+" ORDER BY name");for(auto row:r.rows){TableObject o;o.kind=TableObjectKind::Trigger;o.name=o.originalName=row[0].toString();o.sql=row[1].toString();o.enabled=!row[2].toBool();if(o.sql.isEmpty())fail("触发器定义不可见，请确认 VIEW DEFINITION 权限");d.objects<<o;}
    }else if(k==K::Oracle){
        auto where=" WHERE owner="+l(d.node.schema)+" AND table_name="+l(d.node.object);auto r=q("SELECT comments FROM all_tab_comments"+where);if(!r.rows.isEmpty())d.comment=r.rows[0][0].toString();r=q("SELECT column_name,comments FROM all_col_comments"+where);for(auto row:r.rows)for(auto& c:d.columns)if(c.name==row[0].toString())c.comment=row[1].toString();r=q("SELECT tablespace_name FROM all_tables"+where);if(!r.rows.isEmpty())d.tablespace=r.rows[0][0].toString();
        r=q("SELECT c.constraint_name,c.constraint_type,c.search_condition,c.status,c.deferrable,c.deferred FROM all_constraints c WHERE c.owner="+l(d.node.schema)+" AND c.table_name="+l(d.node.object)+" ORDER BY c.constraint_name");for(auto row:r.rows){auto type=row[1].toString();if(type=="P"){d.primaryKeyName=row[0].toString();continue;}if(type!="U" && type!="R" && type!="C")continue;TableObject o;o.name=o.originalName=row[0].toString();o.enabled=row[3].toString()=="ENABLED";o.deferrable=row[4].toString()=="DEFERRABLE";o.initiallyDeferred=row[5].toString()=="DEFERRED";
            if(type=="C"){o.kind=TableObjectKind::Check;o.expression=row[2].toString();if(o.name.startsWith("SYS_C") && o.expression.contains(QRegularExpression("^\"[^\"]+\" IS NOT NULL$",QRegularExpression::CaseInsensitiveOption)))continue;if(o.expression.isEmpty())fail("检查约束定义不可见");}
            else {auto fields=q("SELECT column_name FROM all_cons_columns WHERE owner="+l(d.node.schema)+" AND constraint_name="+l(o.name)+" ORDER BY position");for(auto f:fields.rows)o.columns<<f[0].toString();if(type=="U"){o.kind=TableObjectKind::Index;o.unique=o.constraint=true;o.expression=formatIdentifierList(o.columns,k);}else{o.kind=TableObjectKind::ForeignKey;auto refs=q("SELECT r.owner,r.table_name,rc.column_name,c.delete_rule FROM all_constraints c JOIN all_constraints r ON r.owner=c.r_owner AND r.constraint_name=c.r_constraint_name JOIN all_cons_columns rc ON rc.owner=r.owner AND rc.constraint_name=r.constraint_name WHERE c.owner="+l(d.node.schema)+" AND c.constraint_name="+l(o.name)+" ORDER BY rc.position");for(auto f:refs.rows){o.referenceSchema=f[0].toString();o.referenceTable=f[1].toString();o.referenceColumns<<f[2].toString();o.onDelete=f[3].toString();}}}d.objects<<o;}
        r=q("SELECT i.index_name,i.uniqueness FROM all_indexes i WHERE i.table_owner="+l(d.node.schema)+" AND i.table_name="+l(d.node.object)+" AND NOT EXISTS(SELECT 1 FROM all_constraints c WHERE c.index_owner=i.owner AND c.index_name=i.index_name) ORDER BY i.index_name");for(auto row:r.rows){TableObject o;o.name=o.originalName=row[0].toString();o.unique=row[1].toString()=="UNIQUE";auto ddl=q("SELECT DBMS_METADATA.GET_DDL('INDEX',"+l(o.name)+","+l(d.node.schema)+") FROM dual");if(ddl.rows.isEmpty())fail("索引定义不可见");parseIndex(o,ddl.rows[0][0].toString(),k);d.objects<<o;}
        r=q("SELECT trigger_name,status FROM all_triggers WHERE table_owner="+l(d.node.schema)+" AND table_name="+l(d.node.object)+" ORDER BY trigger_name");for(auto row:r.rows){TableObject o;o.kind=TableObjectKind::Trigger;o.name=o.originalName=row[0].toString();o.enabled=row[1].toString()=="ENABLED";auto ddl=q("SELECT DBMS_METADATA.GET_DDL('TRIGGER',"+l(o.name)+","+l(d.node.schema)+") FROM dual");if(ddl.rows.isEmpty())fail("触发器定义不可见");o.sql=ddl.rows[0][0].toString();d.objects<<o;}
    }
    d.detailsLoaded=true;
}
}
